import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

// Generated by scripts/export-webflow.mjs from the Webflow "Stories" collection.
const caseStudies = defineCollection({
  loader: glob({ pattern: '*.md', base: './src/content/case-studies' }),
  schema: ({ image }) =>
    z.object({
      title: z.string(),
      slug: z.string(),
      category: z.enum(['Case Study', 'Insights', 'Poster', 'Workshop', 'Blog']).nullable(),
      author: z.string().nullable(),
      shortDescription: z.string().nullable(),
      blogImage: z.object({ src: image(), alt: z.string().nullable(), webflowFileId: z.string().nullable() }).nullable(),
      mainStory: z.boolean().nullable(),
      orderNumber: z.number().nullable(),
      status: z.object({ isDraft: z.boolean(), isArchived: z.boolean(), published: z.boolean() }),
      webflowId: z.string(),
      createdOn: z.coerce.date(),
      lastUpdated: z.coerce.date(),
      lastPublished: z.coerce.date().nullable(),
    }),
});

export const collections = { caseStudies };
